public class InnerHarnessHarnessSkillFactory(Action<Humidifier.BedrockAgentCore.HarnessTypes.HarnessSkill> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.HarnessTypes.HarnessSkill>
{

    internal InnerHarnessHarnessSkillS3SourceFactory S3Factory { get; set; }

    internal InnerHarnessHarnessSkillGitSourceFactory GitFactory { get; set; }

    internal InnerHarnessHarnessSkillAwsSkillsSourceFactory AwsSkillsFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.HarnessTypes.HarnessSkill Create()
    {
        var harnessSkillResult = CreateHarnessSkill();
        factoryAction?.Invoke(harnessSkillResult);

        return harnessSkillResult;
    }

    private Humidifier.BedrockAgentCore.HarnessTypes.HarnessSkill CreateHarnessSkill()
    {
        var harnessSkillResult = new Humidifier.BedrockAgentCore.HarnessTypes.HarnessSkill();

        return harnessSkillResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.HarnessTypes.HarnessSkill result)
    {
        base.CreateChildren(result);

        result.S3 ??= S3Factory?.Build();
        result.Git ??= GitFactory?.Build();
        result.AwsSkills ??= AwsSkillsFactory?.Build();
    }

} // End Of Class

